#include <stdio.h>
#include <stdlib.h>

#define MAX_EDGES 600000

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int *head = malloc((size_t)n * sizeof(int));
    int *to = malloc((size_t)MAX_EDGES * sizeof(int));
    int *next = malloc((size_t)MAX_EDGES * sizeof(int));
    int *color = calloc((size_t)n, sizeof(int));
    int *stack = malloc((size_t)n * sizeof(int));

    for (int i = 0; i < n; i++) head[i] = -1;

    int edges = 0;
    for (int i = 0; i < n; i++) {
        int m;
        scanf("%d", &m);
        while (m--) {
            int x;
            scanf("%d", &x);
            to[edges] = x - 1;
            next[edges] = head[i];
            head[i] = edges++;
        }
    }

    for (int start = 0; start < n; start++) {
        if (color[start]) continue;

        int top = 0;
        color[start] = start == 0 ? 1 : 1;
        stack[top++] = start;

        while (top > 0) {
            int v = stack[--top];
            for (int e = head[v]; e != -1; e = next[e]) {
                int u = to[e];
                if (!color[u]) {
                    color[u] = 3 - color[v];
                    stack[top++] = u;
                }
            }
        }
    }

    for (int team = 1; team <= 2; team++) {
        int first = 1;
        for (int i = 0; i < n; i++) {
            if (color[i] == team) {
                if (!first) putchar(' ');
                printf("%d", i + 1);
                first = 0;
            }
        }
        putchar('\n');
    }

    free(head);
    free(to);
    free(next);
    free(color);
    free(stack);
    return 0;
}
